// SMILES isocyanate CSD — root-cause fix + incremental diversity improvement.
//
// Root-cause audit of 0% syntax in attempts 32-34:
//   Guidance in those attempts explicitly showed R-first examples like
//   "Clc1ccc(N=C=O)cc1". The model generated the INCOMPLETE prefix
//   "Clc1ccc(N=C=O)" (ring unclosed). The SMILES grammar parser returned
//   IsCompletePrefix = true for this permissive prefix. The NCO substring
//   check "N=C=O" matched inside "Clc1ccc(N=C=O)" → premature span close
//   → RDKit rejected the incomplete ring → 0% syntax.
//
// Core fix:
//   Use ONLY O-first form examples in guidance (O=C=N-R, not R-N=C=O).
//   Attempt 9 (20% accuracy, 100% syntax) used exactly this form.
//   The substring "N=C=O" does NOT appear in "O=C=NCC(F)(F)F" or similar
//   O-first SMILES → the NCO check with "N=C=O" alone is dead code for
//   O-first form, so premature close cannot occur.
//
// Improvement over attempt 9:
//   1. Add "O=C=N" as a second substring check so the isocyanate test
//      actually fires for O-first complete SMILES (active early-close path).
//   2. Extend the penalty phase from 6 tokens to 8 tokens to push the model
//      further into diverse structural space before committing.
//   3. Add bromoalkyl and ether-chain O-first examples to the guidance to
//      widen structural coverage without introducing R-first patterns.
//   4. Keep CloseSpanWithinBudget as a robust fallback for any residual
//      open spans at budget exhaustion.
//
// Prediction: 100% syntax (O-first guidance prevents premature ring close);
//   accuracy above 20% (longer penalty phase + O=C=N early-close + broader guidance).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut))
//
//   OpenConstrainedSpan: sets currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by method precondition. ✓
//
//   Loop — IsCompletePrefix + hasIsocyanate branch: CloseConstrainedSpan
//     sets insideConstrainedOut := false → implication vacuously true;
//     currentConstrainedOut := [] satisfies the !inside clause. ✓
//
//   Loop — IsCompletePrefix + noIsocyanate (continue) branch:
//     SafeTemperatureConstrainedStep hard-masks to parser-valid tokens + EOS;
//     AppendConstrainedToken postcondition gives parser.IsValidPrefix(new
//     currentConstrainedOut). EOS → break, invariant holds vacuously. ✓
//
//   Loop — phase1 (SafePenalizedConstrainedStep): hard-mask contract +
//     AppendConstrainedToken preserves parser validity. ✓
//
//   Loop — phase2 (SafeTemperatureConstrainedStep): same hard-mask contract. ✓
//
//   Loop — phase3 (GroupBoostedConstrainedStep): same hard-mask contract. ✓
//
//   EOS close branch: gated on parser.IsCompletePrefix AND steps < maxSteps;
//     CloseConstrainedSpan postcondition clears insideConstrainedOut. ✓
//
//   Post-loop CloseSpanWithinBudget: postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress (|generated| <= |generatedPrefix| + steps)
//
//   OpenConstrainedSpan: steps += 1, |generated| grows by exactly 1 ("<<").
//     |generated| = |generatedPrefix| + 1 = |generatedPrefix| + steps. ✓
//
//   Each loop iteration: exactly one constrained-step call → steps += 1.
//     AppendConstrainedToken adds at most 1 visible token (step already counted).
//     CloseConstrainedSpan inside loop: steps += 1, |generated| += 1 (">>"). ✓
//     EOS path (no append): steps += 1, |generated| unchanged. ✓
//     EOS + close path: steps += 2 total (EOS + close), |generated| += 1. ✓
//     After loop body: |generated| <= |generatedPrefix| + steps. ✓
//
//   Post-loop CloseSpanWithinBudget: closeBudget = maxSteps - steps.
//     Postcondition: |cg| <= |generated| + closeBudget
//                       <= |generatedPrefix| + steps + (maxSteps - steps)
//                        = |generatedPrefix| + maxSteps.
//     We set steps := maxSteps, preserving invariant at method exit. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid SMILES for an isocyanate molecule containing N=C=O. Be maximally diverse. Try these structural classes: fluoroalkyl isocyanates (e.g., O=C=NCC(F)(F)F), chloroalkyl (O=C=NCCCl), bromoalkyl (O=C=NCCBr), cyclopentyl (O=C=NC1CCCC1), cyclohexyl (O=C=NC1CCCCC1), benzyl (O=C=NCc1ccccc1), naphthyl (O=C=Nc1ccc2ccccc2c1), pyridyl (O=C=Nc1ccccn1), tert-butyl (O=C=NC(C)(C)C), allyl (O=C=NCC=C), propargyl (O=C=NCC#C), ether-chain (O=C=NCCOC). Output ONLY the SMILES string.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var ncoCount := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    var ocnCount := CSDHelpers.CountSubstring(smilesStr, "O=C=N");
    if ncoCount > 0 || ocnCount > 0 {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 8 {
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 22 {
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
    } else {
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr2 := CSDHelpers.PrefixToString(currentConstrainedOut);
        var ncoCount2 := CSDHelpers.CountSubstring(smilesStr2, "N=C=O");
        var ocnCount2 := CSDHelpers.CountSubstring(smilesStr2, "O=C=N");
        if ncoCount2 > 0 || ocnCount2 > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

